<?php
namespace App\Interfaces\Http\Controllers\Api\V1\Logistics;
use App\Application\Audit\AuditWriter;use App\Application\Logistics\Adapters\CourierAdapterRegistry;use App\Application\Logistics\DeliveryOtpNotifier;use App\Domain\Logistics\FulfilmentStateMachine;use Illuminate\Http\{JsonResponse,Request};use Illuminate\Support\Facades\{DB,Hash};use Illuminate\Support\Str;
final class FulfilmentController{
public function availability(Request$r,CourierAdapterRegistry$registry):JsonResponse{$d=$r->validate(['delivery_address'=>'required|array']);$t=app(\App\Domain\Tenancy\TenantContext::class)->id();$couriers=$registry->for('INTERNAL')->checkAvailability($t,$d['delivery_address']);return response()->json(['data'=>['available'=>count($couriers)>0,'couriers'=>$couriers]]);}
public function store(Request$r,AuditWriter$a,DeliveryOtpNotifier$otpNotifier){$d=$r->validate(['policy_id'=>'required|uuid|exists:policies,id','delivery_address'=>'required|array','sla_due_at'=>'required|date|after:now','idempotency_key'=>'required|string|max:100']);$t=app(\App\Domain\Tenancy\TenantContext::class)->id();$policy=DB::table('policies')->where(['id'=>$d['policy_id'],'tenant_id'=>$t,'status'=>'ACTIVE'])->first();abort_unless($policy,422);if($o=DB::table('fulfilment_orders')->where(['tenant_id'=>$t,'idempotency_key'=>$d['idempotency_key']])->first())return response()->json(['data'=>$o]);$otp=(string)random_int(100000,999999);$id=(string)Str::uuid();DB::table('fulfilment_orders')->insert(['id'=>$id,'tenant_id'=>$t,'policy_id'=>$d['policy_id'],'status'=>'CREATED','delivery_address'=>json_encode($d['delivery_address']),'sla_due_at'=>$d['sla_due_at'],'delivery_otp_hash'=>Hash::make($otp),'delivery_attempts'=>0,'idempotency_key'=>$d['idempotency_key'],'created_at'=>now(),'updated_at'=>now()]);$otpNotifier->notify($policy->party_id,$otp);$a->record('fulfilment.created','fulfilment_order',$id,['policy_id'=>$d['policy_id']]);return response()->json(['data'=>['id'=>$id,'status'=>'CREATED','delivery_otp_sent'=>true]],201);}
public function transition(Request$r,string$order,FulfilmentStateMachine$m,AuditWriter$a){$d=$r->validate(['to_status'=>'required|in:READY_FOR_PICKUP,ASSIGNED,PICKED_UP,IN_TRANSIT,DELIVERED,FAILED_ATTEMPT,RETURNING,RETURNED,CANCELLED','courier_id'=>'nullable|uuid|exists:couriers,id','delivery_otp'=>'nullable|string|size:6','latitude'=>'nullable|numeric|between:-90,90','longitude'=>'nullable|numeric|between:-180,180','evidence'=>'sometimes|array']);$t=app(\App\Domain\Tenancy\TenantContext::class)->id();return DB::transaction(function()use($r,$d,$order,$m,$a,$t){$o=DB::table('fulfilment_orders')->where(['tenant_id'=>$t,'id'=>$order])->lockForUpdate()->first();abort_unless($o,404);$m->assert($o->status,$d['to_status']);if(!empty($d['courier_id']))abort_unless(DB::table('couriers')->where(['id'=>$d['courier_id'],'tenant_id'=>$t,'status'=>'ACTIVE'])->exists(),422);if($d['to_status']==='DELIVERED')abort_unless(!empty($d['delivery_otp'])&&Hash::check($d['delivery_otp'],$o->delivery_otp_hash),422);$u=['status'=>$d['to_status'],'updated_at'=>now()];if(!empty($d['courier_id']))$u['courier_id']=$d['courier_id'];if($d['to_status']==='ASSIGNED'&&!$o->tracking_number)$u['tracking_number']='TRK-'.strtoupper(Str::random(12));if($d['to_status']==='FAILED_ATTEMPT')$u['delivery_attempts']=$o->delivery_attempts+1;if($d['to_status']==='DELIVERED'){$u['delivered_at']=now();$u['proof_of_delivery']=json_encode($d['evidence']??[]);}DB::table('fulfilment_orders')->where('id',$order)->update($u);DB::table('fulfilment_events')->insert(['id'=>(string)Str::uuid(),'fulfilment_order_id'=>$order,'from_status'=>$o->status,'to_status'=>$d['to_status'],'event_type'=>'STATUS_CHANGED','courier_id'=>$d['courier_id']??$o->courier_id,'actor_id'=>$r->user()->id,'latitude'=>$d['latitude']??null,'longitude'=>$d['longitude']??null,'evidence'=>json_encode($d['evidence']??[]),'occurred_at'=>now()]);$a->record('fulfilment.transitioned','fulfilment_order',$order,['from'=>$o->status,'to'=>$d['to_status']]);return response()->json(['data'=>['id'=>$order,'status'=>$d['to_status']]]);});}}
